.bt-a-xxl.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xxl.ne.on, .bt-a-xxl.ne.active {
  color: #3b3844;
}
.bt-a-xxl.ne.on i, .bt-a-xxl.ne.active i {
  filter: brightness(1);
}
.bt-a-xxl.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xxl.ne:hover, .bt-a-xxl.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-xxl.ne:focus-visible, .bt-a-xxl.ne:active, .bt-a-xxl.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-xxl.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xxl.ne.on, .bt-a-xxl.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
