.bt-a-xxl.de {
  background-color: #e61e21;
  border-color: #e61e21;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xxl.de.on, .bt-a-xxl.de.active {
  color: #e61e21;
}
.bt-a-xxl.de.on i, .bt-a-xxl.de.active i {
  filter: brightness(1);
}
.bt-a-xxl.de:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xxl.de:hover, .bt-a-xxl.de.hover {
  background-color: #cf0d11;
  border-color: #cf0d11;
}
.bt-a-xxl.de:focus-visible, .bt-a-xxl.de:active, .bt-a-xxl.de.press {
  background-color: #ac0a0c;
  border-color: #ac0a0c;
}
.bt-a-xxl.de:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xxl.de.on, .bt-a-xxl.de.active {
  color: #e61e21;
  background-color: #ffffff;
  border-color: #e61e21;
}
