.bt-a-xxl.ca {
  background-color: #eaa810;
  border-color: #eaa810;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xxl.ca.on, .bt-a-xxl.ca.active {
  color: #eaa810;
}
.bt-a-xxl.ca.on i, .bt-a-xxl.ca.active i {
  filter: brightness(1);
}
.bt-a-xxl.ca:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xxl.ca:hover, .bt-a-xxl.ca.hover {
  background-color: #ce940d;
  border-color: #ce940d;
}
.bt-a-xxl.ca:focus-visible, .bt-a-xxl.ca:active, .bt-a-xxl.ca.press {
  background-color: #ae7c0a;
  border-color: #ae7c0a;
}
.bt-a-xxl.ca:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xxl.ca.on, .bt-a-xxl.ca.active {
  color: #eaa810;
  background-color: #ffffff;
  border-color: #eaa810;
}
.bt-a-xxl.su:focus-visible {
