.bt-a-xxl.su {
  background-color: #41c028;
  border-color: #41c028;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xxl.su.on, .bt-a-xxl.su.active {
  color: #41c028;
}
.bt-a-xxl.su.on i, .bt-a-xxl.su.active i {
  filter: brightness(1);
}
.bt-a-xxl.su:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xxl.su:hover, .bt-a-xxl.su.hover {
  background-color: #20bf00;
  border-color: #20bf00;
}
.bt-a-xxl.su:focus-visible, .bt-a-xxl.su:active, .bt-a-xxl.su.press {
  background-color: #1dad00;
  border-color: #1dad00;
}
.bt-a-xxl.su:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xxl.su.on, .bt-a-xxl.su.active {
  color: #41c028;
  background-color: #ffffff;
  border-color: #41c028;
}
.bt-a-xxl.if:focus-visible {
  outline: 5px solid rgba(14, 171, 239, 0.08);
  outline-offset: 0px;
}
.bt-a-xxl.if i {
