.bt-a-xxl.if i.loading > * {
  background: #0eabef;
}
.bt-a-xxl.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xxl.if.on, .bt-a-xxl.if.active {
  color: #0eabef;
}
.bt-a-xxl.if.on i, .bt-a-xxl.if.active i {
  filter: brightness(1);
}
.bt-a-xxl.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xxl.if:hover, .bt-a-xxl.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-xxl.if:focus-visible, .bt-a-xxl.if:active, .bt-a-xxl.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-xxl.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xxl.if.on, .bt-a-xxl.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

.bt-a-xl {
  height: 6.4rem;
  font-size: clamp(1.8rem, 1.9531vw, 2rem);
  padding: 1.9rem 2rem;
}
@media screen and (max-width: 960px) {
  .bt-a-xl {
    height: 4.8rem;
    font-size: clamp(2.2rem, 2.5391vw, 2.6rem);
    padding: 1.3rem 2rem;
    gap: 0.3rem;
  }
}
.bt-a-xl:focus-visible {
  outline: 5px solid rgba(247, 247, 252, 0.08);
  outline-offset: 0px;
}
.bt-a-xl i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
