.bt-a-xl i.loading > * {
  background: #3b3844;
}
.bt-a-xl {
  background-color: #f7f7fc;
  border-color: #f7f7fc;
  color: #ffffff;
  transition: all 300ms ease-in-out;
  color: #8d869b;
}
.bt-a-xl i {
  filter: brightness(0.9);
}
.bt-a-xl.on, .bt-a-xl.active {
  color: #3b3844;
}
.bt-a-xl.on i, .bt-a-xl.active i {
  filter: brightness(0.6);
}
.bt-a-xl:hover, .bt-a-xl.hover {
  background-color: #f3f3f8;
  border-color: #f3f3f8;
}
.bt-a-xl:focus-visible, .bt-a-xl:active, .bt-a-xl.press {
  background-color: #e0dfe8;
  border-color: #e0dfe8;
}
.bt-a-xl:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.on, .bt-a-xl.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-xl.po:focus-visible {
  outline: 5px solid rgba(10, 96, 169, 0.08);
  outline-offset: 0px;
}
.bt-a-xl.po i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
