.bt-a-xl.po {
  background-color: #0a60a9;
  border-color: #0a60a9;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.po.on, .bt-a-xl.po.active {
  color: #0a60a9;
}
.bt-a-xl.po.on i, .bt-a-xl.po.active i {
  filter: brightness(1);
}
.bt-a-xl.po:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.po:hover, .bt-a-xl.po.hover {
  background-color: #09518d;
  border-color: #09518d;
}
.bt-a-xl.po:focus-visible, .bt-a-xl.po:active, .bt-a-xl.po.press {
  background-color: #094374;
  border-color: #094374;
}
.bt-a-xl.po:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.po.on, .bt-a-xl.po.active {
  color: #0a60a9;
  background-color: #ffffff;
  border-color: #0a60a9;
}
