.bt-a-xl.sb {
  background-color: #f18a00;
  border-color: #f18a00;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.sb.on, .bt-a-xl.sb.active {
  color: #f18a00;
}
.bt-a-xl.sb.on i, .bt-a-xl.sb.active i {
  filter: brightness(1);
}
.bt-a-xl.sb:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.sb:hover, .bt-a-xl.sb.hover {
  background-color: #d37900;
  border-color: #d37900;
}
.bt-a-xl.sb:focus-visible, .bt-a-xl.sb:active, .bt-a-xl.sb.press {
  background-color: #b16600;
  border-color: #b16600;
}
.bt-a-xl.sb:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.sb.on, .bt-a-xl.sb.active {
  color: #f18a00;
  background-color: #ffffff;
  border-color: #f18a00;
}
