.bt-a-xl.ne i.loading > * {
  background: #3b3844;
}
.bt-a-xl.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.ne.on, .bt-a-xl.ne.active {
  color: #3b3844;
}
.bt-a-xl.ne.on i, .bt-a-xl.ne.active i {
  filter: brightness(1);
}
.bt-a-xl.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.ne:hover, .bt-a-xl.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-xl.ne:focus-visible, .bt-a-xl.ne:active, .bt-a-xl.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-xl.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.ne.on, .bt-a-xl.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-xl.de:focus-visible {
  outline: 5px solid rgba(230, 30, 33, 0.08);
  outline-offset: 0px;
}
.bt-a-xl.de i {
  display: flex;
  height: 1lh;
