.bt-a-xl.de {
  background-color: #e61e21;
  border-color: #e61e21;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.de.on, .bt-a-xl.de.active {
  color: #e61e21;
}
.bt-a-xl.de.on i, .bt-a-xl.de.active i {
  filter: brightness(1);
}
.bt-a-xl.de:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.de:hover, .bt-a-xl.de.hover {
  background-color: #cf0d11;
  border-color: #cf0d11;
}
.bt-a-xl.de:focus-visible, .bt-a-xl.de:active, .bt-a-xl.de.press {
  background-color: #ac0a0c;
  border-color: #ac0a0c;
}
.bt-a-xl.de:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.de.on, .bt-a-xl.de.active {
  color: #e61e21;
  background-color: #ffffff;
  border-color: #e61e21;
}
.bt-a-xl.ca:focus-visible {
