.bt-a-xl.ca {
  background-color: #eaa810;
  border-color: #eaa810;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.ca.on, .bt-a-xl.ca.active {
  color: #eaa810;
}
.bt-a-xl.ca.on i, .bt-a-xl.ca.active i {
  filter: brightness(1);
}
.bt-a-xl.ca:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.ca:hover, .bt-a-xl.ca.hover {
  background-color: #ce940d;
  border-color: #ce940d;
}
.bt-a-xl.ca:focus-visible, .bt-a-xl.ca:active, .bt-a-xl.ca.press {
  background-color: #ae7c0a;
  border-color: #ae7c0a;
}
.bt-a-xl.ca:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.ca.on, .bt-a-xl.ca.active {
  color: #eaa810;
  background-color: #ffffff;
  border-color: #eaa810;
}
.bt-a-xl.su:focus-visible {
