.bt-a-xl.if i.loading > * {
  background: #0eabef;
}
.bt-a-xl.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xl.if.on, .bt-a-xl.if.active {
  color: #0eabef;
}
.bt-a-xl.if.on i, .bt-a-xl.if.active i {
  filter: brightness(1);
}
.bt-a-xl.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xl.if:hover, .bt-a-xl.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-xl.if:focus-visible, .bt-a-xl.if:active, .bt-a-xl.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-xl.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xl.if.on, .bt-a-xl.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

.bt-a-l {
  height: 4.8rem;
  font-size: clamp(1.6rem, 1.7578vw, 1.8rem);
  padding: 1.3rem 2rem;
}
@media screen and (max-width: 960px) {
  .bt-a-l {
    height: 4rem;
    font-size: clamp(1.4rem, 1.5625vw, 1.6rem);
    padding: 1.3rem 2rem;
    gap: 0.3rem;
  }
}
.bt-a-l:focus-visible {
  outline: 5px solid rgba(247, 247, 252, 0.08);
  outline-offset: 0px;
}
.bt-a-l i {
