.bt-a-l.po i.loading > * {
  background: #0a60a9;
}
.bt-a-l.po {
  background-color: #0a60a9;
  border-color: #0a60a9;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-l.po.on, .bt-a-l.po.active {
  color: #0a60a9;
}
.bt-a-l.po.on i, .bt-a-l.po.active i {
  filter: brightness(1);
}
.bt-a-l.po:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-l.po:hover, .bt-a-l.po.hover {
  background-color: #09518d;
  border-color: #09518d;
}
.bt-a-l.po:focus-visible, .bt-a-l.po:active, .bt-a-l.po.press {
  background-color: #094374;
  border-color: #094374;
}
.bt-a-l.po:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-l.po.on, .bt-a-l.po.active {
  color: #0a60a9;
  background-color: #ffffff;
  border-color: #0a60a9;
}
.bt-a-l.sb:focus-visible {
  outline: 5px solid rgba(241, 138, 0, 0.08);
  outline-offset: 0px;
}
.bt-a-l.sb i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
