.bt-a-l.sb i.loading > * {
  background: #f18a00;
}
.bt-a-l.sb {
  background-color: #f18a00;
  border-color: #f18a00;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-l.sb.on, .bt-a-l.sb.active {
  color: #f18a00;
}
.bt-a-l.sb.on i, .bt-a-l.sb.active i {
  filter: brightness(1);
}
.bt-a-l.sb:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-l.sb:hover, .bt-a-l.sb.hover {
  background-color: #d37900;
  border-color: #d37900;
}
.bt-a-l.sb:focus-visible, .bt-a-l.sb:active, .bt-a-l.sb.press {
  background-color: #b16600;
  border-color: #b16600;
}
.bt-a-l.sb:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-l.sb.on, .bt-a-l.sb.active {
  color: #f18a00;
  background-color: #ffffff;
  border-color: #f18a00;
}
.bt-a-l.ne:focus-visible {
  outline: 5px solid rgba(59, 56, 68, 0.08);
  outline-offset: 0px;
}
.bt-a-l.ne i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
