.bt-a-l.ne i.loading > * {
  background: #3b3844;
}
.bt-a-l.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-l.ne.on, .bt-a-l.ne.active {
  color: #3b3844;
}
.bt-a-l.ne.on i, .bt-a-l.ne.active i {
  filter: brightness(1);
}
.bt-a-l.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-l.ne:hover, .bt-a-l.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-l.ne:focus-visible, .bt-a-l.ne:active, .bt-a-l.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-l.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-l.ne.on, .bt-a-l.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-l.de:focus-visible {
  outline: 5px solid rgba(230, 30, 33, 0.08);
  outline-offset: 0px;
}
.bt-a-l.de i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
