.bt-a-l.if i.loading > * {
  background: #0eabef;
}
.bt-a-l.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-l.if.on, .bt-a-l.if.active {
  color: #0eabef;
}
.bt-a-l.if.on i, .bt-a-l.if.active i {
  filter: brightness(1);
}
.bt-a-l.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-l.if:hover, .bt-a-l.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-l.if:focus-visible, .bt-a-l.if:active, .bt-a-l.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-l.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-l.if.on, .bt-a-l.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

.bt-a-m {
  height: 4rem;
  font-size: clamp(1.4rem, 1.5625vw, 1.6rem);
  padding: 1rem;
}
@media screen and (max-width: 960px) {
  .bt-a-m {
    height: 3.2rem;
    font-size: clamp(1.2rem, 1.3672vw, 1.4rem);
    padding: 0.7rem;
    gap: 0.3rem;
  }
}
.bt-a-m:focus-visible {
  outline: 5px solid rgba(247, 247, 252, 0.08);
  outline-offset: 0px;
}
.bt-a-m i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
