.bt-a-m i.loading > * {
  background: #3b3844;
}
.bt-a-m {
  background-color: #f7f7fc;
  border-color: #f7f7fc;
  color: #ffffff;
  transition: all 300ms ease-in-out;
  color: #8d869b;
}
.bt-a-m i {
  filter: brightness(0.9);
}
.bt-a-m.on, .bt-a-m.active {
  color: #3b3844;
}
.bt-a-m.on i, .bt-a-m.active i {
  filter: brightness(0.6);
}
.bt-a-m:hover, .bt-a-m.hover {
  background-color: #f3f3f8;
  border-color: #f3f3f8;
}
.bt-a-m:focus-visible, .bt-a-m:active, .bt-a-m.press {
  background-color: #e0dfe8;
  border-color: #e0dfe8;
}
.bt-a-m:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.on, .bt-a-m.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-m.po:focus-visible {
  outline: 5px solid rgba(10, 96, 169, 0.08);
  outline-offset: 0px;
}
.bt-a-m.po i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
