.bt-a-m.sb i.loading > * {
  background: #f18a00;
}
.bt-a-m.sb {
  background-color: #f18a00;
  border-color: #f18a00;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-m.sb.on, .bt-a-m.sb.active {
  color: #f18a00;
}
.bt-a-m.sb.on i, .bt-a-m.sb.active i {
  filter: brightness(1);
}
.bt-a-m.sb:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-m.sb:hover, .bt-a-m.sb.hover {
  background-color: #d37900;
  border-color: #d37900;
}
.bt-a-m.sb:focus-visible, .bt-a-m.sb:active, .bt-a-m.sb.press {
  background-color: #b16600;
  border-color: #b16600;
}
.bt-a-m.sb:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.sb.on, .bt-a-m.sb.active {
  color: #f18a00;
  background-color: #ffffff;
  border-color: #f18a00;
}
.bt-a-m.ne:focus-visible {
  outline: 5px solid rgba(59, 56, 68, 0.08);
  outline-offset: 0px;
}
.bt-a-m.ne i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
