.bt-a-m.ne i.loading > * {
  background: #3b3844;
}
.bt-a-m.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-m.ne.on, .bt-a-m.ne.active {
  color: #3b3844;
}
.bt-a-m.ne.on i, .bt-a-m.ne.active i {
  filter: brightness(1);
}
.bt-a-m.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-m.ne:hover, .bt-a-m.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-m.ne:focus-visible, .bt-a-m.ne:active, .bt-a-m.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-m.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.ne.on, .bt-a-m.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-m.de:focus-visible {
  outline: 5px solid rgba(230, 30, 33, 0.08);
  outline-offset: 0px;
}
.bt-a-m.de i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
