.bt-a-m.de i.loading > * {
  background: #e61e21;
}
.bt-a-m.de {
  background-color: #e61e21;
  border-color: #e61e21;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-m.de.on, .bt-a-m.de.active {
  color: #e61e21;
}
.bt-a-m.de.on i, .bt-a-m.de.active i {
  filter: brightness(1);
}
.bt-a-m.de:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-m.de:hover, .bt-a-m.de.hover {
  background-color: #cf0d11;
  border-color: #cf0d11;
}
.bt-a-m.de:focus-visible, .bt-a-m.de:active, .bt-a-m.de.press {
  background-color: #ac0a0c;
  border-color: #ac0a0c;
}
.bt-a-m.de:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.de.on, .bt-a-m.de.active {
  color: #e61e21;
  background-color: #ffffff;
  border-color: #e61e21;
}
.bt-a-m.ca:focus-visible {
  outline: 5px solid rgba(234, 168, 16, 0.08);
  outline-offset: 0px;
}
.bt-a-m.ca i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
