.bt-a-m.ca i.loading > * {
  background: #eaa810;
}
.bt-a-m.ca {
  background-color: #eaa810;
  border-color: #eaa810;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-m.ca.on, .bt-a-m.ca.active {
  color: #eaa810;
}
.bt-a-m.ca.on i, .bt-a-m.ca.active i {
  filter: brightness(1);
}
.bt-a-m.ca:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-m.ca:hover, .bt-a-m.ca.hover {
  background-color: #ce940d;
  border-color: #ce940d;
}
.bt-a-m.ca:focus-visible, .bt-a-m.ca:active, .bt-a-m.ca.press {
  background-color: #ae7c0a;
  border-color: #ae7c0a;
}
.bt-a-m.ca:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.ca.on, .bt-a-m.ca.active {
  color: #eaa810;
  background-color: #ffffff;
  border-color: #eaa810;
}
.bt-a-m.su:focus-visible {
  outline: 5px solid rgba(65, 192, 40, 0.08);
  outline-offset: 0px;
}
.bt-a-m.su i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
