.bt-a-m.if i.loading > * {
  background: #0eabef;
}
.bt-a-m.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-m.if.on, .bt-a-m.if.active {
  color: #0eabef;
}
.bt-a-m.if.on i, .bt-a-m.if.active i {
  filter: brightness(1);
}
.bt-a-m.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-m.if:hover, .bt-a-m.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-m.if:focus-visible, .bt-a-m.if:active, .bt-a-m.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-m.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-m.if.on, .bt-a-m.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

.bt-a-s {
  height: 3.2rem;
  font-size: clamp(1.2rem, 1.3672vw, 1.4rem);
  padding: 0.7rem;
}
@media screen and (max-width: 960px) {
  .bt-a-s {
    height: 2.4rem;
    font-size: 1.2rem;
    padding: 0.5rem;
    gap: 0.3rem;
  }
}
.bt-a-s:focus-visible {
  outline: 5px solid rgba(247, 247, 252, 0.08);
  outline-offset: 0px;
}
.bt-a-s i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
