.bt-a-s i.loading > * {
  background: #3b3844;
}
.bt-a-s {
  background-color: #f7f7fc;
  border-color: #f7f7fc;
  color: #ffffff;
  transition: all 300ms ease-in-out;
  color: #8d869b;
}
.bt-a-s i {
  filter: brightness(0.9);
}
.bt-a-s.on, .bt-a-s.active {
  color: #3b3844;
}
.bt-a-s.on i, .bt-a-s.active i {
  filter: brightness(0.6);
}
.bt-a-s:hover, .bt-a-s.hover {
  background-color: #f3f3f8;
  border-color: #f3f3f8;
}
.bt-a-s:focus-visible, .bt-a-s:active, .bt-a-s.press {
  background-color: #e0dfe8;
  border-color: #e0dfe8;
}
.bt-a-s:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.on, .bt-a-s.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-s.po:focus-visible {
  outline: 5px solid rgba(10, 96, 169, 0.08);
  outline-offset: 0px;
}
.bt-a-s.po i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
