.bt-a-s.po i.loading > * {
  background: #0a60a9;
}
.bt-a-s.po {
  background-color: #0a60a9;
  border-color: #0a60a9;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.po.on, .bt-a-s.po.active {
  color: #0a60a9;
}
.bt-a-s.po.on i, .bt-a-s.po.active i {
  filter: brightness(1);
}
.bt-a-s.po:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.po:hover, .bt-a-s.po.hover {
  background-color: #09518d;
  border-color: #09518d;
}
.bt-a-s.po:focus-visible, .bt-a-s.po:active, .bt-a-s.po.press {
  background-color: #094374;
  border-color: #094374;
}
.bt-a-s.po:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.po.on, .bt-a-s.po.active {
  color: #0a60a9;
  background-color: #ffffff;
  border-color: #0a60a9;
}
.bt-a-s.sb:focus-visible {
  outline: 5px solid rgba(241, 138, 0, 0.08);
  outline-offset: 0px;
}
.bt-a-s.sb i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
