.bt-a-s.sb i.loading > * {
  background: #f18a00;
}
.bt-a-s.sb {
  background-color: #f18a00;
  border-color: #f18a00;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.sb.on, .bt-a-s.sb.active {
  color: #f18a00;
}
.bt-a-s.sb.on i, .bt-a-s.sb.active i {
  filter: brightness(1);
}
.bt-a-s.sb:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.sb:hover, .bt-a-s.sb.hover {
  background-color: #d37900;
  border-color: #d37900;
}
.bt-a-s.sb:focus-visible, .bt-a-s.sb:active, .bt-a-s.sb.press {
  background-color: #b16600;
  border-color: #b16600;
}
.bt-a-s.sb:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.sb.on, .bt-a-s.sb.active {
  color: #f18a00;
  background-color: #ffffff;
  border-color: #f18a00;
}
.bt-a-s.ne:focus-visible {
  outline: 5px solid rgba(59, 56, 68, 0.08);
  outline-offset: 0px;
}
.bt-a-s.ne i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
