.bt-a-s.ne i.loading > * {
  background: #3b3844;
}
.bt-a-s.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.ne.on, .bt-a-s.ne.active {
  color: #3b3844;
}
.bt-a-s.ne.on i, .bt-a-s.ne.active i {
  filter: brightness(1);
}
.bt-a-s.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.ne:hover, .bt-a-s.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-s.ne:focus-visible, .bt-a-s.ne:active, .bt-a-s.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-s.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.ne.on, .bt-a-s.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-s.de:focus-visible {
  outline: 5px solid rgba(230, 30, 33, 0.08);
  outline-offset: 0px;
}
.bt-a-s.de i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
