.bt-a-s.de i.loading > * {
  background: #e61e21;
}
.bt-a-s.de {
  background-color: #e61e21;
  border-color: #e61e21;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.de.on, .bt-a-s.de.active {
  color: #e61e21;
}
.bt-a-s.de.on i, .bt-a-s.de.active i {
  filter: brightness(1);
}
.bt-a-s.de:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.de:hover, .bt-a-s.de.hover {
  background-color: #cf0d11;
  border-color: #cf0d11;
}
.bt-a-s.de:focus-visible, .bt-a-s.de:active, .bt-a-s.de.press {
  background-color: #ac0a0c;
  border-color: #ac0a0c;
}
.bt-a-s.de:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.de.on, .bt-a-s.de.active {
  color: #e61e21;
  background-color: #ffffff;
  border-color: #e61e21;
}
.bt-a-s.ca:focus-visible {
  outline: 5px solid rgba(234, 168, 16, 0.08);
  outline-offset: 0px;
}
.bt-a-s.ca i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
