.bt-a-s.ca i.loading > * {
  background: #eaa810;
}
.bt-a-s.ca {
  background-color: #eaa810;
  border-color: #eaa810;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.ca.on, .bt-a-s.ca.active {
  color: #eaa810;
}
.bt-a-s.ca.on i, .bt-a-s.ca.active i {
  filter: brightness(1);
}
.bt-a-s.ca:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.ca:hover, .bt-a-s.ca.hover {
  background-color: #ce940d;
  border-color: #ce940d;
}
.bt-a-s.ca:focus-visible, .bt-a-s.ca:active, .bt-a-s.ca.press {
  background-color: #ae7c0a;
  border-color: #ae7c0a;
}
.bt-a-s.ca:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.ca.on, .bt-a-s.ca.active {
  color: #eaa810;
  background-color: #ffffff;
  border-color: #eaa810;
}
.bt-a-s.su:focus-visible {
  outline: 5px solid rgba(65, 192, 40, 0.08);
  outline-offset: 0px;
}
.bt-a-s.su i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
