.bt-a-s.if i.loading > * {
  background: #0eabef;
}
.bt-a-s.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-s.if.on, .bt-a-s.if.active {
  color: #0eabef;
}
.bt-a-s.if.on i, .bt-a-s.if.active i {
  filter: brightness(1);
}
.bt-a-s.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-s.if:hover, .bt-a-s.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-s.if:focus-visible, .bt-a-s.if:active, .bt-a-s.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-s.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-s.if.on, .bt-a-s.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

.bt-a-xs {
  height: 2.4rem;
  font-size: 1.2rem;
  padding: 0.5rem;
}
@media screen and (max-width: 960px) {
  .bt-a-xs {
    height: 2rem;
    font-size: 1.2rem;
    padding: 0.5rem;
    gap: 0.3rem;
  }
}
.bt-a-xs:focus-visible {
  outline: 5px solid rgba(247, 247, 252, 0.08);
  outline-offset: 0px;
}
.bt-a-xs i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
