.bt-a-xs.po i.loading > * {
  background: #0a60a9;
}
.bt-a-xs.po {
  background-color: #0a60a9;
  border-color: #0a60a9;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.po.on, .bt-a-xs.po.active {
  color: #0a60a9;
}
.bt-a-xs.po.on i, .bt-a-xs.po.active i {
  filter: brightness(1);
}
.bt-a-xs.po:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.po:hover, .bt-a-xs.po.hover {
  background-color: #09518d;
  border-color: #09518d;
}
.bt-a-xs.po:focus-visible, .bt-a-xs.po:active, .bt-a-xs.po.press {
  background-color: #094374;
  border-color: #094374;
}
.bt-a-xs.po:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.po.on, .bt-a-xs.po.active {
  color: #0a60a9;
  background-color: #ffffff;
  border-color: #0a60a9;
}
.bt-a-xs.sb:focus-visible {
