.bt-a-xs.sb i.loading > * {
  background: #f18a00;
}
.bt-a-xs.sb {
  background-color: #f18a00;
  border-color: #f18a00;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.sb.on, .bt-a-xs.sb.active {
  color: #f18a00;
}
.bt-a-xs.sb.on i, .bt-a-xs.sb.active i {
  filter: brightness(1);
}
.bt-a-xs.sb:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.sb:hover, .bt-a-xs.sb.hover {
  background-color: #d37900;
  border-color: #d37900;
}
.bt-a-xs.sb:focus-visible, .bt-a-xs.sb:active, .bt-a-xs.sb.press {
  background-color: #b16600;
  border-color: #b16600;
}
.bt-a-xs.sb:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.sb.on, .bt-a-xs.sb.active {
  color: #f18a00;
  background-color: #ffffff;
  border-color: #f18a00;
}
.bt-a-xs.ne:focus-visible {
