.bt-a-xs.ne i.loading > * {
  background: #3b3844;
}
.bt-a-xs.ne {
  background-color: #3b3844;
  border-color: #3b3844;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.ne.on, .bt-a-xs.ne.active {
  color: #3b3844;
}
.bt-a-xs.ne.on i, .bt-a-xs.ne.active i {
  filter: brightness(1);
}
.bt-a-xs.ne:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.ne:hover, .bt-a-xs.ne.hover {
  background-color: #25242d;
  border-color: #25242d;
}
.bt-a-xs.ne:focus-visible, .bt-a-xs.ne:active, .bt-a-xs.ne.press {
  background-color: #111017;
  border-color: #111017;
}
.bt-a-xs.ne:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.ne.on, .bt-a-xs.ne.active {
  color: #3b3844;
  background-color: #ffffff;
  border-color: #3b3844;
}
.bt-a-xs.de:focus-visible {
  outline: 5px solid rgba(230, 30, 33, 0.08);
  outline-offset: 0px;
}
.bt-a-xs.de i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
