.bt-a-xs.de i.loading > * {
  background: #e61e21;
}
.bt-a-xs.de {
  background-color: #e61e21;
  border-color: #e61e21;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.de.on, .bt-a-xs.de.active {
  color: #e61e21;
}
.bt-a-xs.de.on i, .bt-a-xs.de.active i {
  filter: brightness(1);
}
.bt-a-xs.de:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.de:hover, .bt-a-xs.de.hover {
  background-color: #cf0d11;
  border-color: #cf0d11;
}
.bt-a-xs.de:focus-visible, .bt-a-xs.de:active, .bt-a-xs.de.press {
  background-color: #ac0a0c;
  border-color: #ac0a0c;
}
.bt-a-xs.de:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.de.on, .bt-a-xs.de.active {
  color: #e61e21;
  background-color: #ffffff;
  border-color: #e61e21;
}
.bt-a-xs.ca:focus-visible {
  outline: 5px solid rgba(234, 168, 16, 0.08);
  outline-offset: 0px;
}
.bt-a-xs.ca i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
