.bt-a-xs.ca i.loading > * {
  background: #eaa810;
}
.bt-a-xs.ca {
  background-color: #eaa810;
  border-color: #eaa810;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.ca.on, .bt-a-xs.ca.active {
  color: #eaa810;
}
.bt-a-xs.ca.on i, .bt-a-xs.ca.active i {
  filter: brightness(1);
}
.bt-a-xs.ca:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.ca:hover, .bt-a-xs.ca.hover {
  background-color: #ce940d;
  border-color: #ce940d;
}
.bt-a-xs.ca:focus-visible, .bt-a-xs.ca:active, .bt-a-xs.ca.press {
  background-color: #ae7c0a;
  border-color: #ae7c0a;
}
.bt-a-xs.ca:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.ca.on, .bt-a-xs.ca.active {
  color: #eaa810;
  background-color: #ffffff;
  border-color: #eaa810;
}
.bt-a-xs.su:focus-visible {
  outline: 5px solid rgba(65, 192, 40, 0.08);
  outline-offset: 0px;
}
.bt-a-xs.su i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
