.bt-a-xs.su i.loading > * {
  background: #41c028;
}
.bt-a-xs.su {
  background-color: #41c028;
  border-color: #41c028;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.su.on, .bt-a-xs.su.active {
  color: #41c028;
}
.bt-a-xs.su.on i, .bt-a-xs.su.active i {
  filter: brightness(1);
}
.bt-a-xs.su:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.su:hover, .bt-a-xs.su.hover {
  background-color: #20bf00;
  border-color: #20bf00;
}
.bt-a-xs.su:focus-visible, .bt-a-xs.su:active, .bt-a-xs.su.press {
  background-color: #1dad00;
  border-color: #1dad00;
}
.bt-a-xs.su:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.su.on, .bt-a-xs.su.active {
  color: #41c028;
  background-color: #ffffff;
  border-color: #41c028;
}
.bt-a-xs.if:focus-visible {
  outline: 5px solid rgba(14, 171, 239, 0.08);
  outline-offset: 0px;
}
.bt-a-xs.if i {
  display: flex;
  height: 1lh;
  aspect-ratio: 1/1;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}
