.bt-a-xs.if i.loading > * {
  background: #0eabef;
}
.bt-a-xs.if {
  background-color: #0eabef;
  border-color: #0eabef;
  color: #ffffff;
  transition: all 300ms ease-in-out;
}
.bt-a-xs.if.on, .bt-a-xs.if.active {
  color: #0eabef;
}
.bt-a-xs.if.on i, .bt-a-xs.if.active i {
  filter: brightness(1);
}
.bt-a-xs.if:not(.on, .active) i {
  filter: brightness(100);
}
.bt-a-xs.if:hover, .bt-a-xs.if.hover {
  background-color: #0d98d4;
  border-color: #0d98d4;
}
.bt-a-xs.if:focus-visible, .bt-a-xs.if:active, .bt-a-xs.if.press {
  background-color: #0d87bb;
  border-color: #0d87bb;
}
.bt-a-xs.if:focus-visible {
  outline: 2px dotted #3b3844;
  outline-offset: 4px;
}
.bt-a-xs.if.on, .bt-a-xs.if.active {
  color: #0eabef;
  background-color: #ffffff;
  border-color: #0eabef;
}

