.bt-b-xxl.if {
  background-color: #ffffff;
  border-color: #0eabef;
  color: #0eabef;
  font-weight: 500;
}
.bt-b-xxl.if:hover, .bt-b-xxl.if.hover {
  border-color: #0d98d4;
  background-color: rgba(13, 135, 187, 0.05);
}
.bt-b-xxl.if:active, .bt-b-xxl.if.press {
  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-xxl.if:active i, .bt-b-xxl.if.press i {
  filter: brightness(0.9);
}
.bt-b-xxl.if.on, .bt-b-xxl.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-xxl.if.on i, .bt-b-xxl.if.active i {
  filter: brightness(100);
}

