.bt-b-xl.if {
  background-color: #ffffff;
  border-color: #0eabef;
  color: #0eabef;
  font-weight: 500;
}
.bt-b-xl.if:hover, .bt-b-xl.if.hover {
  border-color: #0d98d4;
  background-color: rgba(13, 135, 187, 0.05);
}
.bt-b-xl.if:active, .bt-b-xl.if.press {
  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-xl.if:active i, .bt-b-xl.if.press i {
  filter: brightness(0.9);
}
.bt-b-xl.if.on, .bt-b-xl.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-xl.if.on i, .bt-b-xl.if.active i {
  filter: brightness(100);
}

