  background: #0eabef;
}
.bt-b-l.if {
  background-color: #ffffff;
  border-color: #0eabef;
  color: #0eabef;
  font-weight: 500;
}
.bt-b-l.if:hover, .bt-b-l.if.hover {
  border-color: #0d98d4;
  background-color: rgba(13, 135, 187, 0.05);
}
.bt-b-l.if:active, .bt-b-l.if.press {
  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-l.if:active i, .bt-b-l.if.press i {
  filter: brightness(0.9);
}
.bt-b-l.if.on, .bt-b-l.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-l.if.on i, .bt-b-l.if.active i {
  filter: brightness(100);
}

.bt-b-m {
  height: 4rem;
