.bt-b-m.if {
  background-color: #ffffff;
  border-color: #0eabef;
  color: #0eabef;
  font-weight: 500;
}
.bt-b-m.if:hover, .bt-b-m.if.hover {
  border-color: #0d98d4;
  background-color: rgba(13, 135, 187, 0.05);
}
.bt-b-m.if:active, .bt-b-m.if.press {
  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-m.if:active i, .bt-b-m.if.press i {
  filter: brightness(0.9);
}
.bt-b-m.if.on, .bt-b-m.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-m.if.on i, .bt-b-m.if.active i {
  filter: brightness(100);
}

