.bt-b-s.if {
  background-color: #ffffff;
  border-color: #0eabef;
  color: #0eabef;
  font-weight: 500;
}
.bt-b-s.if:hover, .bt-b-s.if.hover {
  border-color: #0d98d4;
  background-color: rgba(13, 135, 187, 0.05);
}
.bt-b-s.if:active, .bt-b-s.if.press {
  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-s.if:active i, .bt-b-s.if.press i {
  filter: brightness(0.9);
}
.bt-b-s.if.on, .bt-b-s.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-s.if.on i, .bt-b-s.if.active i {
  filter: brightness(100);
}

