  background-color: rgba(13, 135, 187, 0.1);
  border-color: #0d87bb;
  color: #0d87bb;
}
.bt-b-xs.if:active i, .bt-b-xs.if.press i {
  filter: brightness(0.9);
}
.bt-b-xs.if.on, .bt-b-xs.if.active {
  background-color: #0eabef;
  color: #ffffff;
}
.bt-b-xs.if.on i, .bt-b-xs.if.active i {
  filter: brightness(100);
}

