.card-profile .card-item .data li span {
  position: absolute;
  width: max-content;
  opacity: 0;
  top: 50%;
  left: 2rem;
  font-size: clamp(1.4rem, 1.5625vw, 1.6rem);
  transform: translate(-100%, -50%);
  color: #9590a2;
  border-radius: 100rem;
  padding: 1rem;
  background: #ffffff;
  transition: all 300ms ease-in-out;
  line-height: 1.4;
}
