  opacity: 1;
  left: 0%;
}
@container cardList (max-width: 500px) {
  .card-profile .card-item {
    flex-direction: column;
    align-items: flex-start;
  }
  .card-profile .card-item [class^=ava-] {
    width: 30vw;
  }
  .card-profile .card-item .data li {
    display: flex;
    align-items: center;
    gap: 0.8rem;
  }
  .card-profile .card-item .data li i {
    flex-shrink: 0;
  }
  .card-profile .card-item .data li span {
    opacity: 1;
    transform: unset;
    position: unset;
    padding: 0;
    line-height: 1.4;
    text-box: trim-both cap alphabetic;
    width: auto;
    flex-grow: 1;
    word-break: break-all;
    transition: none;
  }
}

