  display: flex;
  align-items: center;
  gap: 1rem;
  color: #3b3844;
  outline: none;
  font-weight: 600;
  padding: 2rem;
  cursor: pointer;
}
.acd-m details summary em {
  font-size: clamp(1.2rem, 1.3672vw, 1.4rem);
  line-height: 1;
  text-box: trim-both cap alphabetic;
  display: block;
  background: #3b3844;
  color: #ffffff;
  font-weight: 300;
  padding: 0.9rem 1.2rem 1rem;
  border-radius: 100rem;
  flex-shrink: 0;
}
.acd-m details summary::marker {
  content: "";
}
.acd-m details summary::after {
  content: "";
  width: 3rem;
  aspect-ratio: 1/1;
  position: absolute;
  right: 1.3333333333rem;
  top: calc(50% - 0.2rem);
  transform: translateY(-50%);
