  transition: transform 0.3s ease;
}
.acd-m details[open] summary::after {
  transform: translateY(-50%) rotate(180deg);
}
.acd-m details::details-content {
  block-size: 0;
  overflow: clip;
  transition: block-size 300ms ease-in-out, margin-top 300ms ease-in-out, opacity 300ms ease-in-out, content-visibility 300ms ease-in-out allow-discrete;
  opacity: 0;
}
.acd-m details[open]::details-content {
  block-size: auto;
  opacity: 1;
}
.acd-m details summary + div {
  border-top: 0.1rem solid #e0dfe8;
  line-height: 1.4;
  padding: 2rem 0;
  width: calc(100% - 4rem);
  margin: 0 auto;
}

